import type { MetadataRoute } from "next";

/**
 * /robots.txt — generated by Next's App Router metadata convention.
 *
 * Crawlers may index the public marketing/product surface but never the admin
 * console, the API surface, or the internal dev-skeleton preview. `sitemap`
 * points bots at the canonical URL set below.
 */
const SITE_URL = process.env.NEXT_PUBLIC_SITE_URL?.trim() || "https://robincalls.com";

// `/agent/` and `/mcp` are the AI plane's live API surface (nginx proxies both
// to the FastAPI container), not pages. Nothing there renders for a reader, and
// `/agent/tool` spends real RPC on whoever calls it.
const DISALLOW = ["/admin", "/api/", "/agent/", "/mcp", "/dev-skeleton-check", "/dev/"];

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      { userAgent: "*", allow: "/", disallow: DISALLOW },
      // Redundant with the "*" rule above (every one of these already
      // inherits Allow: /) — named explicitly anyway so the intent to be
      // crawled and cited by answer engines (GEO) is a decision on record,
      // not an accident of not having blocked them, and so a future change
      // that tightens "*" doesn't silently pull these along with it.
      {
        userAgent: [
          "GPTBot",
          "OAI-SearchBot",
          "ChatGPT-User",
          "ClaudeBot",
          "anthropic-ai",
          "PerplexityBot",
          "Google-Extended",
          "CCBot",
        ],
        allow: "/",
        disallow: DISALLOW,
      },
    ],
    sitemap: `${SITE_URL}/sitemap.xml`,
    host: SITE_URL,
  };
}
